import {assetHref} from "./data-loader.js";
import {courses} from "./catalogue-data.js";
import { sequenceModel, goalFields } from './sequence-model.js';
import { mount } from '../slides/widgets.js';
const P=(fr,en)=>[fr,en], E=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const steps=[['prepare',P('Se préparer','Prepare')],['experiment',P('Chercher','Investigate')],['understand',P('Construire le cours','Build the lesson')],['practice',P('S’entraîner','Practise')],['review',P('Faire le bilan','Review')],['documents',P('Supports','Resources')]];
const kinds={chapter:P('Livret élève','Student booklet'),teacher:P('Corrigés et guide professeur','Solutions and teacher guide'),fluency:P('Automatismes','Fluency'),'fluency-solutions':P('Corrigés des automatismes','Fluency solutions')};
const courseNames={seconde:'Seconde',premiere:'Première spécialité',terminale:'Terminale spécialité',stmg:'Terminale STMG'};
export function chapterSequencePage(c,tab,t,chapters){
 tab=steps.some(([k])=>k===tab)?tab:'prepare';
 const prev=chapters.find(x=>x.course===c.course&&x.number===c.number-1),next=chapters.find(x=>x.course===c.course&&x.number===c.number+1);
 return `<main id="main" tabindex="-1" class="page chapter-page sequence-page"><a class="back-library" href="#resources">${t(P('Tous les chapitres','All chapters'))}</a><div class="chapter-heading"><p class="muted">${E(t(courses.find(x=>x.id===c.course)?.title||[c.course,c.course]))} · ${t(P('Chapitre','Chapter'))} ${c.number}</p><h1>${E(t(c.title))}</h1></div><div class="sequence-layout"><nav class="sequence-nav" aria-label="${t(P('Progression du chapitre','Chapter progression'))}"><ol>${steps.map(([k,label],i)=>`<li><a href="#chapter/${c.id}/${k}" ${k===tab?'aria-current="step"':''}><span>${i+1}</span>${E(t(label))}</a></li>`).join('')}</ol><a class="sequence-slides" href="${E(assetHref("./slides/player.html"))}&amp;deck=${c.id}">${t(P('Présenter et manipuler','Present and explore'))} ↗</a></nav><section class="sequence-content" id="chapter-sequence" data-step="${tab}" aria-busy="true">${tab==='documents'?chapterDocuments(c,t(P('fr','en'))==='en'?1:0):`<p role="status">${t(P('Chargement du chapitre…','Loading chapter…'))}</p>`}</section></div><nav class="chapter-next" aria-label="${t(P('Ordre des chapitres','Chapter order'))}">${prev?`<a href="#chapter/${prev.id}">← ${E(t(prev.title))}</a>`:'<span></span>'}${next?`<a href="#chapter/${next.id}">${E(t(next.title))} →</a>`:''}</nav></main>`;
}
let mathPromise;
async function math(root){
 if(!mathPromise){mathPromise=(async()=>{
  if(!window.MathJax?.startup?.promise){
   window.MathJax={startup:{typeset:false},svg:{fontCache:'none'},options:{enableAssistiveMml:false},tex:{inlineMath:[['\\(','\\)']],displayMath:[['\\[','\\]']],macros:{pgcd:'\\operatorname{PGCD}',ppcm:'\\operatorname{PPCM}',N:'\\mathbb{N}',Z:'\\mathbb{Z}',Q:'\\mathbb{Q}',R:'\\mathbb{R}',C:'\\mathbb{C}',vect:['\\overrightarrow{#1}',1],norm:['\\left\\lVert #1\\right\\rVert',1],abs:['\\left\\lvert #1\\right\\rvert',1],dd:'\\,\\mathrm{d}',e:'\\mathrm{e}',E:'\\operatorname{E}',V:'\\operatorname{V}',Card:'\\operatorname{Card}',vi:'\\vec{\\imath}',vj:'\\vec{\\jmath}',vk:'\\vec{k}',vc:['\\begin{pmatrix}#1\\\\#2\\end{pmatrix}',2],deter:['\\det\\left(#1,#2\\right)',2],degre:'^{\\circ}',un:['\\,\\mathrm{#1}',1],sci:['#1\\times10^{#2}',2]}}};
   await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./vendor/mathjax-tex-svg.js';s.onload=resolve;s.onerror=reject;document.head.append(s);});
  }
  await window.MathJax.startup.promise;
 })();}
 try {await mathPromise;if(root.isConnected){await window.MathJax.typesetPromise([root]);root.querySelectorAll('mjx-assistive-mml').forEach(x=>x.remove());}}catch{mathPromise=null;}
}
function fileLink(f,L,label,page=1){if(!f)return '';const path=L?f.englishPath:f.path;if(!path)return '';const bytes=L?f.englishBytes:f.bytes;return `<a class="document-link" href="./${E(assetHref(path))}#page=${page}" target="_blank" rel="noopener">${E(label)}<span>PDF · ${f.pages} p.${bytes?' · '+Math.round(bytes/1024)+(L?' KB':' Ko'):''}</span></a>`;}
function slideBody(s,id,L){if(s.k==='code')return `<pre class="sequence-code"><code>${E((s.b[L]||'').replaceAll('&lt;','<').replaceAll('&gt;','>').replaceAll('&amp;','&'))}</code></pre>`;const figs=(s.f||[]).map(p=>`<figure class="sequence-figure"><img loading="lazy" src="./slides/fig/${id}-${p[L]}${L?'-en':''}.svg" alt="${E(s.t[L])}"></figure>`).join('');return `<div class="sequence-maths">${s.b[L]||''}</div>${figs}`;}
function taskHelp(s,L){return (s.hints||[]).map((hint,i)=>`<details><summary>${P('Aide','Hint')[L]} ${i+1}</summary><div class="sequence-maths">${hint[L]}</div></details>`).join('');}
function questionCards(items,c,L){return items.map(s=>`<article class="sequence-card"><h3>${E(s.t[L])}</h3>${slideBody(s,c.id,L)}${taskHelp(s,L)}${s.a?`<details><summary>${P('Correction : après une réponse rédigée','Solution: after writing your answer')[L]}</summary><div class="sequence-maths">${s.a[L]}</div></details>`:''}</article>`).join('');}
function chapterDocuments(c,L){return `<h2>${P('Les supports du chapitre','Chapter resources')[L]}</h2><p>${P('Le cours web, le livret complet et le diaporama ont des usages complémentaires. Choisis le support selon la tâche.','The web lesson, complete booklet and slide deck serve complementary purposes. Choose the resource for your task.')[L]}</p><div class="sequence-documents">${c.files.map(f=>{const label=(kinds[f.kind]||P('Document','Document'))[L]+(f.title?' · '+f.title[L]:'');const link=fileLink(f,L,label);return ['teacher','fluency-solutions'].includes(f.kind)?`<details class="sequence-card"><summary>${E(label)}</summary>${link}</details>`:`<article class="sequence-card">${link}</article>`;}).join('')}<article class="sequence-card"><h3>${P('Présenter et manipuler','Present and explore')[L]}</h3><a href="${E(assetHref("./slides/player.html"))}&amp;deck=${c.id}">${P('Ouvrir le diaporama interactif','Open the interactive slide deck')[L]} ↗</a> <a href="${E(assetHref(`./slides/export/${c.id}.html`))}" download>${P("Télécharger HTML","Download HTML")[L]}</a></article></div>`;}
export function mountChapterSequence(c,t){
 const root=document.getElementById('chapter-sequence');if(!root)return()=>{};
 const L=t(P('fr','en'))==='en'?1:0;let cancelled=false,live=[];const controller=new AbortController();
 (async()=>{
  try{
   const r=await fetch(assetHref(`./slides/data/${encodeURIComponent(c.id)}.json`),{cache:"no-store",signal:controller.signal});if(!r.ok)throw Error(r.status);const deck=await r.json();if(cancelled)return;
   const model=sequenceModel(deck),step=root.dataset.step,fields=goalFields(model.goals,L),chapter=c.files.find(f=>f.kind==='chapter'),teacher=c.files.find(f=>f.kind==='teacher');
   if(!fields.length && model.tasks.length)fields.push({label:P('Objectifs proposés à partir des tâches du chapitre','Suggested objectives drawn from the chapter tasks')[L],body:'<ol>'+model.tasks.slice(0,4).map(s=>'<li>'+s.b[L]+'</li>').join('')+'</ol>'});
   const lessonIndex=`<ol class="sequence-index">${model.lessons.map((s,i)=>`<li><a href="#chapter/${c.id}/understand/${i}">${E(s.title[L])}</a></li>`).join('')}</ol>`;
   const intro=P('Travaille dans l’ordre : prépare tes acquis, cherche, puis formalise et entraîne-toi. Chaque étape reprend les contenus de ce chapitre.','Work in order: prepare what you know, investigate, then formalise and practise. Each step uses this chapter’s own content.')[L];
   let html='';
   if(step==='prepare')html=`<h2>${P('Avant de commencer','Before starting')[L]}</h2><p class="sequence-lead">${intro}</p><div class="sequence-objectives">${fields.map(f=>`<section><h3>${E(f.label)}</h3><div class="sequence-maths">${f.body}</div></section>`).join('')||`<p>${P('Le parcours porte sur les notions suivantes.','The sequence covers the following ideas.')[L]}</p>`}</div><h3>${P('La progression','The progression')[L]}</h3>${lessonIndex}${c.files.filter(f=>f.kind==='fluency').map(f=>fileLink(f,L,P('Vérifier les automatismes avant le chapitre','Check fluency before starting')[L])).join('')}<p class="sequence-note">${P('Les objectifs ci-dessus viennent du chapitre. Ils ne constituent pas une nouvelle prescription de programme.','The objectives above come from the chapter; they are not a new curriculum requirement.')[L]}</p>${questionCards(model.diagnostics,c,L)}`;
   if(step==='experiment'){
    html=`<h2>${P('Chercher avant de formaliser','Investigate before formalising')[L]}</h2><p>${P('Fais une prévision, teste-la, puis formule une conjecture. Une observation ne remplace pas une démonstration.','Make a prediction, test it, then formulate a conjecture. Observation does not replace proof.')[L]}</p>`;
    html+=model.activities.map((s,i)=>s.k==='widget'?`<article class="sequence-card"><h3>${E(s.t[L])}</h3><p>${E(s.w.type==='quad'?P('Déplace les deux points pour observer la courbe. Ses zéros sont les abscisses des intersections avec l’axe horizontal. Formule une conjecture avant de consulter le cours.','Move the two points to observe the curve. Its zeros are the x-coordinates of intersections with the horizontal axis. Make a conjecture before reading the lesson.')[L]:s.b[L])}</p><div class="sequence-experiment" data-widget="${i}"><p class="hint-line"></p><div class="canvas-wrap"></div><div class="wctl"></div><div class="readout"></div></div><details><summary>${P('Mettre en commun','Discuss the findings')[L]}</summary><ul><li>${P('Qu’as-tu modifié ? Qu’est-ce qui reste invariant ?','What did you change? What stayed invariant?')[L]}</li><li>${P('Écris ta conjecture et indique les cas que tu as testés.','Write your conjecture and state the cases you tested.')[L]}</li><li>${P('Cherche un cas qui pourrait la contredire.','Look for a case that could contradict it.')[L]}</li></ul></details></article>`:`<article class="sequence-card"><h3>${E(s.t[L])}</h3>${slideBody(s,c.id,L)}${taskHelp(s,L)}${s.a?`<details><summary>${P('Comparer après la recherche','Compare after investigating')[L]}</summary>${s.a[L]}</details>`:''}</article>`).join('');
    if(!model.activities.length)html+=`<p>${P('Ce chapitre ne contient pas encore d’activité interactive dédiée. Commence par une question du livret, sur papier, avant de consulter le cours.','This chapter does not yet have a dedicated interactive activity. Start with a booklet question on paper before reading the lesson.')[L]}</p>${fileLink(chapter,L,P('Ouvrir le livret élève','Open the student booklet')[L])}`;
   }
   if(step==='understand')html=`<h2>${P('Construire la trace écrite','Build the written lesson')[L]}</h2><p>${P('Chaque notion est suivie d’un exemple et des points de vigilance qui lui correspondent.','Each idea is followed by a related example and points to watch.')[L]}</p><nav aria-label="${P('Notions','Ideas')[L]}"><ol class="sequence-index">${model.lessons.map((s,i)=>`<li><a href="#chapter/${c.id}/understand/${i}" data-scroll="notion-${i}">${E(s.title[L])}</a></li>`).join('')}</ol></nav>${model.lessons.map((s,i)=>`<article class="sequence-card" id="notion-${i}"><h3><span class="sequence-number">${i+1}</span> ${E(s.title[L])}</h3>${s.statements.map(x=>`<section class="sequence-statement">${x.k==='proof'?`<h4>${P('Justifier et démontrer','Justify and prove')[L]}</h4>`:''}${slideBody(x,c.id,L)}</section>`).join('')}${s.examples.map(x=>`<section class="sequence-example"><h4>${P('Exemple résolu','Worked example')[L]}</h4>${slideBody(x,c.id,L)}${x.a?`<details><summary>${P('Dérouler la résolution','Reveal the worked solution')[L]}</summary><div class="sequence-maths">${x.a[L]}</div></details>`:''}</section>`).join('')}${s.warnings.length?`<aside class="sequence-warning"><h4>${P('Points de vigilance','Points to watch')[L]}</h4>${s.warnings.map(x=>slideBody(x,c.id,L)).join('')}</aside>`:''}${s.tasks.length?`<a class="sequence-task-link" href="#chapter/${c.id}/practice">${P('S’entraîner sur cette notion','Practise this idea')[L]} →</a>`:''}</article>`).join('')}`;
   if(step==='practice')html=`<h2>${P('S’entraîner et réinvestir','Practise and apply')[L]}</h2><p>${P('Rédige une réponse justifiée avant d’ouvrir une aide ou une correction. Les questions suivent l’ordre des notions du cours.','Write a justified answer before opening help or solutions. The questions follow the lesson’s order.')[L]}</p>${model.tasks.map((s,i)=>`<article class="sequence-card"><p class="muted">${s.reused?P('Refaire l’exemple sans aide','Redo the example without help')[L]:P('Exercice','Exercise')[L]} ${i+1} · ${E(s.lesson[L])}</p>${slideBody(s,c.id,L)}${taskHelp(s,L)}<details><summary>${P('Aide : retrouver la notion et l’exemple','Help: revisit the idea and example')[L]}</summary><a href="#chapter/${c.id}/understand">${P('Revenir au cours','Back to the lesson')[L]}</a></details>${s.a?`<details><summary>${P('Correction, après avoir cherché','Solution, after trying')[L]}</summary><div class="sequence-maths">${s.a[L]}</div></details>`:''}</article>`).join('')}<section class="sequence-card"><h3>${P('Consolider ou aller plus loin','Consolidate or go further')[L]}</h3>${fileLink(chapter,L,P('Exercices et problèmes du livret','Booklet exercises and problems')[L],chapter?.sections?.practice||1)}<details><summary>${P('Corrigés du livret','Booklet solutions')[L]}</summary>${fileLink(teacher,L,P('Ouvrir la version professeur','Open the teacher edition')[L])}</details></section>`;
   if(step==='review')html=`<h2>${P('Faire le bilan sans le cours','Review without the lesson')[L]}</h2><p>${P('Pour chaque notion, explique la règle avec ses hypothèses, puis refais un exercice sans l’exemple. Une case cochée est un repère personnel, pas une note.','For each idea, explain the rule and its assumptions, then redo an exercise without the example. A checked box is a personal marker, not a grade.')[L]}</p>${questionCards(model.checks,c,L)}<ul class="sequence-checklist">${model.lessons.map((s,i)=>`<li><label><input type="checkbox"> <span>${E(s.title[L])}</span></label><a href="#chapter/${c.id}/understand">${P('Revoir','Revisit')[L]}</a></li>`).join('')}</ul><section class="sequence-card"><h3>${P('Critères de réussite','Success criteria')[L]}</h3><ul><li>${P('J’énonce les conditions de validité du résultat utilisé.','I state the conditions under which the result applies.')[L]}</li><li>${P('Je choisis une méthode et je justifie chaque étape.','I choose a method and justify each step.')[L]}</li><li>${P('Je vérifie mon résultat par substitution, estimation ou autre contrôle adapté.','I check the result by substitution, estimation or another suitable check.')[L]}</li></ul><p>${P('Si une notion reste fragile, reprends son exemple puis la question correspondante dans S’entraîner.','If an idea is still uncertain, revisit its example, then the matching practice question.')[L]}</p></section>`;
   if(step==='documents')html=chapterDocuments(c,L);
   const pos=steps.findIndex(([k])=>k===step);html+=`<nav class="sequence-forward" aria-label="${P('Étape suivante','Next step')[L]}">${pos>0?`<a href="#chapter/${c.id}/${steps[pos-1][0]}">← ${steps[pos-1][1][L]}</a>`:'<span></span>'}${pos<steps.length-1?`<a class="btn btn-primary" href="#chapter/${c.id}/${steps[pos+1][0]}">${steps[pos+1][1][L]} →</a>`:''}</nav>`;
   root.innerHTML=html;root.setAttribute('aria-busy','false');
   root.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();root.querySelector('#'+a.dataset.scroll)?.scrollIntoView({behavior:'instant',block:'start'});});
   root.querySelectorAll('[data-widget]').forEach(el=>{const s=model.activities[+el.dataset.widget];live.push(mount({...s.w,showDelta:false},{host:el.querySelector('.canvas-wrap'),controls:el.querySelector('.wctl'),readout:el.querySelector('.readout'),hint:el.querySelector('.hint-line'),lang:L}));});
   await math(root);
   // #chapter/<id>/understand/<n> opens the lesson at idea n (links from the progression and the idea index).
   const notion=location.hash.split('/')[3];if(!cancelled&&step==='understand'&&notion)root.querySelector('#notion-'+CSS.escape(notion))?.scrollIntoView({behavior:'instant',block:'start'});
  }catch(e){if(cancelled)return;root.setAttribute('aria-busy','false');root.innerHTML=`<p>${P('Le contenu du chapitre ne peut pas être chargé. Les livrets restent disponibles.','The chapter content could not be loaded. The booklets remain available.')[L]}</p>${c.files.map(f=>fileLink(f,L,(kinds[f.kind]||P('Document','Document'))[L])).join('')}`;}
 })();
 return()=>{cancelled=true;controller.abort();live.forEach(x=>x.destroy());};
}
